/**
 * Link version 3, frozen: the settings, config, log and update shapes the channels carry.
 *
 * Written out as concrete types, copied from the shapes the app resolved when link version 3 was cut. It never
 * references the living types, so a change to a handler cannot move it. Do not edit this file to match a changed
 * handler: a change that breaks it needs a new LINK_VERSION and a new `contract/v<N>/` (see protocol.ts for the
 * rule). `tests/remote/contractV3.test.ts` checks the living types against it.
 */

import type { ChallengeValuesV3 } from './shapesChallenges';

export type UpdateSummaryV3 = {
    currentVersion: string;
    latestVersion: string;
    releaseNotes: string;
    releaseDate: null | string;
    isPrerelease: boolean;
};

type ImportRefV3 = {
    holder:
        | { kind: 'rule'; number: number; title?: string }
        | { kind: 'profile'; name: string }
        | { kind: 'challenge'; id: string; title?: string };
    refers: 'profile' | 'scenario';
    name: string;
    invalid?: true;
};

export type ImportReportV3 = { at: string; refsBlocked: (string | ImportRefV3)[]; acknowledged: boolean };

export type LogEntryV3 = {
    seq: number;
    level: 'DEBUG' | 'INFO' | 'WARN' | 'ERROR';
    context: string;
    category: string;
    timestamp: string;
    message: string;
    data: unknown;
    template?: { key: string; params: unknown[] };
};

export type SettingValuesV3V3 = { [key: string]: unknown };

type ChallengePinsV3V3 = { boost?: string; turbo?: string };

export type ChallengeRecordV3V3 = { values?: SettingValuesV3V3; suppressRuleProfile?: true; pins?: ChallengePinsV3V3 };

export type TitleRuleV3 = {
    [key: string]: unknown;
    name?: string;
    title?: string;
    titles?: string[];
    match?: string;
    titleMatchModes?: string[];
    challengeTag?: string;
    type?: string;
    pics?: number;
    minHours?: number;
    maxHours?: number;
    closesAt?: string;
    closesAtTimes?: string[];
    profile?: string;
    mustIncludeTags?: string[];
    shouldIncludeTags?: string[];
};

export type WindowBoundsV3 = { x?: number; y?: number; width: number; height: number };

export type ConfigAppV3 = {
    [key: string]: unknown;
    mock: boolean;
    onboardingCompleted: boolean;
    windowBounds: { login: WindowBoundsV3; main: WindowBoundsV3 };
    theme: string;
    language: string;
    timezone: string;
    customTimezones: string[];
    stayLoggedIn: boolean;
    apiTimeout: number;
    checkFrequencyMin: number;
    checkFrequencyMax: number;
    apiMaxRetries: number;
    apiRetryBaseDelayMs: number;
};

type ImportReportV3V3 = { refsBlocked: (string | ImportRefV3)[] };

export type ImportedV3V3 = {
    at: string;
    report: ImportReportV3V3;
    acknowledged: boolean;
    failure?: { reason: string; detail: string };
};

export type SettingsRecoveryV3 = {
    code: 'settings-import-failed' | 'settings-unreadable' | 'settings-corrupt';
    path: string;
    blocking: boolean;
    detail?: string;
};

export type SettingsSaveDroppedV3 = {
    code: 'settings-save-dropped';
    path: string;
    cause: 'conflict' | 'too-large' | 'storage' | 'logout-lost';
    serial: number;
};

export type SerializableSchemaEntryV3 = {
    default?: unknown;
    type?: string;
    description: string;
    perChallenge?: boolean;
    group?: string;
    label: string;
    helpKey?: string;
    min?: number;
    max?: number;
    unit?: string;
    minutes?: boolean;
    challengeOnly: boolean;
};

export type RuleMatchChallengeV3 = {
    id?: string | number;
    title?: unknown;
    tags?: unknown;
    type?: unknown;
    max_photo_submits?: unknown;
    start_time?: unknown;
    close_time?: unknown;
};

type RuleSourceV3 = { title?: string; index: number; viaProfile?: boolean };

export type TitleRuleInfoV3 = {
    profile: null | { name: string; values: ChallengeValuesV3 };
    suppressed: boolean;
    ruleValues: ChallengeValuesV3;
    inlineValues: ChallengeValuesV3;
    ruleSources: { [key: string]: RuleSourceV3 };
    inlineSources: { [key: string]: RuleSourceV3 };
};

type ConfigAuthV3V3 = { token: string; apiHeaders: { [key: string]: string }; lastUsername: string };

export type ConfigV2V3 = {
    version: 2;
    imported?: ImportedV3V3;
    app: ConfigAppV3;
    auth: ConfigAuthV3V3;
    defaults: SettingValuesV3V3;
    profiles: { [key: string]: unknown };
    seededProfiles: string[];
    scenarios: { [key: string]: unknown };
    rules: TitleRuleV3[];
    challenges: { [key: string]: ChallengeRecordV3V3 };
};

export type DownloadProgressV3 = { percent: number; transferred: number; total: number; bytesPerSecond: number };

export type GuiLogEntryV3 = {
    message: string;
    category: string;
    seq: number;
    level: 'DEBUG' | 'INFO' | 'WARN' | 'ERROR';
    context: string;
    timestamp: string;
    template?: { key: string; params: unknown[] };
};

/** What a full Stop came to: the fence's answer and the withdrawal's, or the remote `requested` arm (the host has not answered yet). */
type StopResultV3 =
    | { outcome: 'stopped'; durable: true; epoch: number; withdrawal: 'withdrawn' | 'none' | 'failed' | 'no-route' }
    | {
          outcome: 'stopped-locally';
          durable: false;
          reason: 'no-fence' | 'unreadable' | 'oversize' | 'not-saved';
          withdrawal: 'withdrawn' | 'none' | 'failed' | 'no-route';
      }
    | { outcome: 'requested'; durable: false };

export type AutovoteStateV3 = {
    running: boolean;
    executionMode: 'stopped' | 'armed' | 'voting';
    stopEpoch: null | number;
    lastStop: null | StopResultV3;
    startRefusal:
        | null
        | 'superseded'
        | 'stop-not-saved'
        | 'fence-unreadable'
        | 'stop-epoch-moved'
        | 'block-not-cleared'
        | 'arm-refused'
        | 'no-armed-cycle';
    cycles: number;
    lastRun: null | string;
    nextRunAt: null | number;
    pendingStartAt: null | number;
    status: 'Error' | 'Stopped' | 'Running';
    statusClass: 'badge-neutral' | 'badge-success' | 'badge-error';
    error: null | string;
};
